{
  "description": "The creature is depicted in right-facing profile standing on a pale, lightly shaded ground. It has the head, ears and muzzle of a wolf at the front of a long, arched neck, joined to a low, elongated quadrupedal body that is almost entirely covered in overlapping dark gray armored plates. The body is supported by four jointed legs ending in clawed paws, with a long tapering segmented tail extending from the rear and curving downward. The dorsal and lateral surfaces from the base of the skull along the neck, back, sides, tail and upper portions of the legs are covered in glossy, overlapping plates with pointed rear edges, while the underside of the chest, belly and lower legs show paler, wrinkled skin and fur. A row of small oval openings is visible along the mid-flank. The overall impression is a single wolf-headed, heavily armored quadruped.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf head with a long pointed muzzle, dark nose, light amber eye, slightly open mouth showing lower teeth, gray and tan fur with darker shading on the crown and lighter fur on the muzzle, chin and throat, and fine whiskers",
      "where": "at the anterior end of the arched neck, facing to the right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two upright, triangular, fur-covered ears with dark interiors and pointed tips",
      "where": "on top of the head, one fully visible in profile and the second partially visible behind it"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy gray and off-white fur forming a ruff around the jaw, throat and base of the neck",
      "where": "encircling the junction of the head and the plated neck"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, jointed walking legs, the upper and outer surfaces covered in dark overlapping plates and the inner and lower surfaces showing pale skin with sparse fur, with visible joints at shoulder, elbow, hip and knee",
      "where": "two forelegs beneath the anterior chest and two hindlegs beneath the posterior body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with pale fur, dark curved claws and padded toes, each with four to five visible digits",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, tapering, heavily segmented tail covered in overlapping dark plates on the dorsal side and smaller ring-like segments ventrally, narrowing to a pointed tip",
      "where": "extending posteriorly from the rear of the body and curving downward toward the ground"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping, glossy dark gray to blackish plates with lighter edges and a slightly ridged, scale-like texture, arranged in transverse rows",
      "where": "covering the dorsal and lateral surfaces of the neck, back, sides, tail and the upper portions of all four legs"
    },
    {
      "part": "shell",
      "looks_like": "a continuous dorsal armor formed by the overlapping plates creating a hard, segmented carapace over the back and sides",
      "where": "over the entire trunk from behind the neck to the base of the tail, wrapping around the sides toward the belly"
    },
    {
      "part": "gills",
      "looks_like": "a row of seven small, vertically oval, dark openings with pale rims set in the lighter skin between the dorsal plates and the belly",
      "where": "along the mid-flank on the side of the trunk between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "armadillo",
    "woodlouse"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
